// Pega o item que chega do nó anterior (Set)
const item = items[0];

// --- CORREÇÃO FINAL: Acesso Direto ao JSON com o nome 'outputFinal' ---
// O nome do campo no nó Set é 'outputFinal'.
// Se a saída do nó Set for um objeto JSON, o caminho é item.json.outputFinal.
const textoBruto = item.json && item.json.outputFinal; // <--- MUDANÇA AQUI!

// Verifica se o texto foi encontrado e é uma string válida
if (!textoBruto || typeof textoBruto !== 'string') {
    // Se o texto não for encontrado, é porque o nó Set não gerou o campo
    // corretamente ou o nome do campo está errado.
    throw new Error('Erro: O texto de entrada não foi encontrado em item.json.outputFinal. Verifique se o nó Set está gerando o campo corretamente.');
}

// Limpa o texto de quebras de linha desnecessárias que podem vir do Agente IA
// e garante que o texto comece com o título.
const textoSujo = textoBruto.replace(/\\n/g, '\n').trim();

// --- Mágica da Limpeza Aprimorada ---

// 1. Divide o texto em linhas
const linhas = textoSujo.split('\n');

// 2. Extrai o título da primeira linha
// Remove marcadores Markdown de título (como '### ')
const titulo_principal = linhas[0].replace(/#+\s*/, '').trim();

// 3. O conteúdo é o restante do texto, a partir da segunda linha.
// Isso é mais seguro do que procurar por '\n\n'.
const conteudo_artigo = linhas.slice(1).join('\n').trim();

// --- Cria o objeto JSON final ---
const resultadoFinal = {
  titulo_principal: titulo_principal,
  conteudo_artigo: conteudo_artigo
};

// Retorna o objeto JSON limpo e pronto para o próximo nó
return [{
  json: resultadoFinal
}];
